    @patch('backend.database.vectorInsert.logging')
    @patch('backend.database.vectorInsert.get_db_connection')
    @patch('backend.database.vectorInsert.get_embeddings')
    def test_insert_embeddings_db_insertion_error(self, mock_get_embeddings, mock_get_db_connection, mock_logging):
        # Sample input data
        text_chunks = ['Sample text 1']

        # Mock the embeddings returned by get_embeddings
        mock_get_embeddings.return_value = [
            {'text': 'Sample text 1', 'embedding': [0.1, 0.2, 0.3]}
        ]

        # Mock the database connection and cursor
        mock_conn = MagicMock()
        mock_cursor = MagicMock()
        mock_conn.cursor.return_value = mock_cursor
        mock_get_db_connection.return_value = mock_conn

        # Configure cursor.execute to raise an exception
        mock_cursor.execute.side_effect = Exception('Database insertion failed')

        # Call the function under test
        insert_embeddings_into_db(text_chunks)

        # Assertions
        mock_get_embeddings.assert_called_once_with(text_chunks)
        mock_get_db_connection.assert_called_once()
        mock_cursor.execute.assert_called_once()
        mock_logging.error.assert_called_with('Database insertion error for Insert 1: Database insertion failed')

        # Ensure that commit and close are still called
        mock_conn.commit.assert_called_once()
        mock_conn.close.assert_called_once()
        mock_cursor.close.assert_called_once()

